package api

import (
	_ "embed"
	"net/http"
)

// openAPISpec is the public OpenAPI 3 spec, generated by scripts/gen-openapi.sh
// from the handler annotations. Only the public endpoints are in it.
//
//go:embed openapi.json
var openAPISpec []byte

// handleOpenAPI serves the public OpenAPI 3 spec.
func (s *Server) handleOpenAPI(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "public, max-age=300")
	_, _ = w.Write(openAPISpec)
}
